// Generated by scripts/emit-keyword-rules.ts from src/lib/arena/glossary.ts and docs/rules/rulemanual.txt. Do not edit.
export interface KeywordRule {
  name: string;
  tag: string;
  /** Lower case, without brackets or placeholder values ("over realm", "awaken: surge"). */
  spellings: string[];
  section: string;
  meaning: string;
  manual: { id: string; text: string }[];
}

export const KEYWORD_RULES: KeywordRule[] = [
  {"name":"Awaken","tag":"[Awaken]","spellings":["awaken","awaken: surge"],"section":"22-2","meaning":"A Leader's own skill. Meet the printed condition, pay the cost, carry out the effect, then flip the Leader onto its awakened side. [Awaken: Surge] is the same skill under another name, and card text saying “[Awaken] skills” means both.","manual":[{"id":"22-2-1","text":"[Awaken] ([Awaken : Surge]) is an [Activate : Main/Battle] skill related to Leaders."},{"id":"22-2-2","text":"[Awaken] ([Awaken : Surge]) is described as follows: \"[Awaken] ([Awaken : Surge]) condition : (effect).\""},{"id":"22-2-2-1","text":"Some card text refers to [Awaken] skills. This refers to both [Awaken] and [Awaken : Surge] skills."},{"id":"22-2-3","text":"[Awaken] ([Awaken : Surge]) can be activated by fulfilling conditions and paying associated costs. These skills can't be activated otherwise."},{"id":"22-2-4","text":"To resolve the effects of [Awaken] ([Awaken : Surge]), carry out the indicated effects, and then--if the card with this skill is face-up--flip it over onto its back."},{"id":"22-2-4-1","text":"The skill text sometimes says to \"flip the card onto its back.\""}]},
  {"name":"Wish","tag":"[Wish]","spellings":["wish"],"section":"22-25","meaning":"The same shape as [Awaken]: a condition, an effect, and then the Leader is flipped over.","manual":[{"id":"22-25-1","text":"This [Activate Main/Battle] keyword skill is related to Leaders."},{"id":"22-25-2","text":"[Wish] is described as follows: \"[Wish] condition : (effect).\""},{"id":"22-25-3","text":"[Wish] can be activated by fulfilling conditions and paying costs. If the conditions can't be fulfilled or the costs can't be paid, [Wish] can't be activated."},{"id":"22-25-4","text":"To resolve the effects of [Wish], execute the specified effects, and then--if the card with [Wish] is face-up--flip it over."},{"id":"22-25-4-1","text":"The skill text might tell you to \"flip the card over.\""}]},
  {"name":"Z-Awaken","tag":"[Z-Awaken]","spellings":["z-awaken"],"section":"22-46","meaning":"From the Z-Deck, once a turn: pay the Z-Energy cost and the skill cost and place this Z-Leader on top of your already-awakened Leader, which has to match the printed description. The stack is one card from then on.","manual":[{"id":"22-46-1","text":"This [Activate : Main/Battle] keyword skill is related to Leaders."},{"id":"22-46-2","text":"[Z-Awaken] is described as follows: \"[Z-Awaken] skill cost : <character name>\" or \"[Z-Awaken] skill cost : specified Leader Card.\" Here, \"<character name>\" and \"specified Leader Card\" are conditions for [Z-Awaken]."},{"id":"22-46-3","text":"[Z-Awaken] can be activated by choosing one specified face-down Leader Card--which must be in your Leader Area and must not be a Z-Card--paying the specified Z-Energy cost, satisfying the specified conditions, and paying the skill cost. If the specified Leader Card can't be chosen, [Z-Awaken] can't be activated."},{"id":"22-46-3-1","text":"Z-Energy costs and skill costs can be paid in any order."},{"id":"22-46-4","text":"[Z-Awaken] can only be declared and activated a total of once per turn."},{"id":"22-46-5","text":"A card with [Z-Awaken] can only be activated if the card is face-down in the Z-Deck Area."},{"id":"22-46-6","text":"To resolve the effects of [Z-Awaken], place the card that activated [Z-Awaken] on top of the Leader Card chosen in 22-46-5. From then on, all the cards under the card that activated [Z-Awaken] are treated as the Z-Leader Card on top and are therefore treated as one card."},{"id":"22-46-6-1","text":"Any continuous effects that affect the original Leader's power or position carry over."},{"id":"22-46-6-2","text":"If the card that activated [Z-Awaken] is not placed in the Leader Area, that card is removed from the game."},{"id":"22-46-6-3","text":"Skills that trigger when \"this card is placed in the Leader Area,\" etc. enter pending."}]},
  {"name":"Z-Stack","tag":"[Z-Stack X]","spellings":["z-stack"],"section":"22-47","meaning":"When this Z-Card is placed on your Leader or into a Battle or Unison Area, put up to X cards matching the printed description from your Z-Deck underneath it. They become part of the card on top.","manual":[{"id":"22-47-1","text":"This [Auto] keyword skill is related to cards in the Z-Deck Area."},{"id":"22-47-2","text":"[Z-Stack X] is described as \"[Z-Stack X] Specified card\" or \"[Z-Stack X] Skill cost : Specified card.\" \"Specified card\" is the condition for [Z- Stack X]."},{"id":"22-47-2-1","text":"Unless specified otherwise, \"Specified card\" is a card that fulfills the conditions from your Z-Deck Area."},{"id":"22-47-3","text":"For [Z-Stack X], a card with this skill in the Z-Deck is made pending when it is placed at the top of a Leader Area or in a Battle Area or Unison Area."},{"id":"22-47-4","text":"The effects of [Z-Stack X] are resolved as follows: Place up to X cards under the card that activated this skill as specified in 22-47-2. Then, all of the cards placed under that card are treated as the same card as the top Z-Card in that stack, and those cards are treated as a single card."},{"id":"22-47-4-1","text":"Some skills read \"when choosing this card's [Z-Stack] conditions, you can choose up to X (condition) cards.\" These skills expand the conditions that can be fulfilled when choosing cards for a given keyword skill."}]},
  {"name":"Field","tag":"[Field]","spellings":["field"],"section":"22-3","meaning":"An Extra Card that stays on the table in Active Mode instead of going to the Drop Area. Its other skills work from there, and playing another [Field] Extra drops the one already out.","manual":[{"id":"22-3-1","text":"[Field] is an [Activate : Main] keyword skill on Extra Cards."},{"id":"22-3-2","text":"The effects of [Field] are resolved as follows: \"Place the Extra Card that activated this skill in the Battle Area in Active Mode.\""},{"id":"22-3-3","text":"If the [Field] skill of a card is activated by another card's skill, the card text might say to \"activate {card name}.\""},{"id":"22-3-4","text":"Extra Cards with [Field] may have other skills as well. Those skills are generally only valid when the card is placed in the Battle Area, and they are activated without placing the card in the Drop Area. (if not specified otherwise)"},{"id":"22-3-4-1","text":"This excludes [Energy Exhaust] skills on [Field] Extra Cards, as they aren't affected by 22-3-4. When such cards are placed in an Energy Area, the [Energy Exhaust] skills place them in Rest Mode."},{"id":"22-3-5","text":"When placing another Extra Card with [Field] in a Battle Area, all other Extra Cards with [Field] in the player's Battle Area are placed in their owner's Drop Area."},{"id":"22-3-5-1","text":"However, when an Extra Card with [Field] is placed under a card in a Battle Area, rule 22-3-5 is ignored."}]},
  {"name":"Evolve","tag":"[Evolve]","spellings":["evolve","ex-evolve","xeno-evolve"],"section":"22-5","meaning":"From hand: pay the cost, choose one of your Battle Cards matching the printed description, and play this card on top of it. [Xeno-Evolve] sends the chosen card to the Warp instead of stacking onto it.","manual":[{"id":"22-5-1","text":"This [Activate : Main] keyword skill is related to playing cards."},{"id":"22-5-2","text":"[Evolve] ([EX-Evolve] [Xeno-Evolve]) is described as follows: \"[Evolve] ([EX-Evolve] [Xeno-Evolve]) skill cost : condition <character name>.\""},{"id":"22-5-2-1","text":"Sometimes conditions are not specified. In these cases, no condition is required."},{"id":"22-5-2-2","text":"Some card text refers to [Evolve] skills. This refers to [Evolve], [EX-Evolve], and [Xeno-Evolve] skills."},{"id":"22-5-2-3","text":"If a card says to \"evolve,\" it means to play the card as if you were to play it with [Evolve] ([EX-Evolve] [Xeno-Evolve])."},{"id":"22-5-2-4","text":"If a card says \"evolved,\" it means a card that was played with [Evolve] ([EX-Evolve] [Xeno-Evolve])."},{"id":"22-5-3","text":"[Evolve] ([EX-Evolve] [Xeno-Evolve]) can be activated by paying the skill cost and choosing one Battle Card with the specified <character name> that fulfills the specified conditions in your Battle Area. If the specified Battle Card can't be chosen, [Evolve] ([EX-Evolve] [Xeno- Evolve]) can't be activated."},{"id":"22-5-3-1","text":"Some card text reads \"when choosing this card's [Evolve] conditions, you can choose a specified Battle Card in your area.\" These skills expand the conditions that can be fulfilled when choosing cards for a given keyword skill."},{"id":"22-5-3-1-1","text":"When using such a skill to choose Battle Cards from an expanded range of areas, if the skill resolution would cause the card that activated [Evolve] to be played, first move any Battle Cards in that area to the Battle Area, and then resolve the keyword skill normally. Furthermore, any area movement triggers resulting from the chosen Battle Card moving to a different area are not made pending, nor does counter timing occur."},{"id":"22-5-4","text":"[Evolve] ([EX-Evolve] [Xeno-Evolve]) can only be activated from a player's hand."},{"id":"22-5-5","text":"When resolving the effects of [Evolve] ([EX-Evolve]), the card that activated this skill is played on top of the Battle Card chosen in 22-5-3. Henceforth, the whole stack of cards is treated as the Battle Card on top, but the position and any effects affecting the prior card's power are carried over (21-5-2)."},{"id":"22-5-5-1","text":"Before resolving the effects of [Evolve] (EX-Evolve), if the Battle Card chosen in 22-5-3 is moved from the Battle Area or if the conditions in 22-5-3 are not fulfilled, [Evolve] (EX-Evolve) fails to resolve."},{"id":"22-5-6","text":"When resolving the effects of [Xeno-Evolve], the Battle Card chosen in 22-5-3 is sent to the Warp, and the card that activated this skill is played."},{"id":"22-5-6-1","text":"Before resolving the effects of [Xeno-Evolve], if the Battle Card chosen in 22-5-3 is moved from the Battle Area or if the conditions in 22-5-3 are not fulfilled, [Xeno-Evolve] fails to resolve."},{"id":"22-5-7","text":"If the card that activated [Evolve] fails to enter play and did not move from its original area due to an effect, it is placed in its owner's Drop Area."},{"id":"22-5-7-1","text":"As an exception to the above rule, if a skill states that a card is \"returned to its owner's hand instead of being played,\" etc., cards returned to a player's hand by such a skill are not placed in their owner's Drop Area."}]},
  {"name":"Union","tag":"[Union-Fusion]","spellings":["union-fusion","union-potara","union-absorb"],"section":"22-13","meaning":"Three ways to play a Battle Card by naming characters. Fusion drops one of each named character from your hand, both of equal power. Potara plays this card on top of two named characters in your Battle Area. Absorb is activated from the Battle Area, and its text says which card is played onto this one.","manual":[{"id":"22-13-1","text":"This [Activate : Main] keyword skill is related to playing cards."},{"id":"22-13-2","text":"[Union] is a general term for a subset of skills that play Battle Cards to Battle Areas from specific areas when certain costs and conditions are fulfilled."},{"id":"22-13-3","text":"[Union] skills are generally formatted [Union-(type)]."},{"id":"22-13-3-1","text":"Some card text refers to [Union] skills. This refers to [Union-Fusion], [Union-Potara], and [Union-Absorb] skills."},{"id":"22-13-4","text":"[Union-Fusion]"},{"id":"22-13-4-1","text":"[Union-Fusion] is described as follows: \"[Union-Fusion] skill cost : <Character Name A> and <Character Name B>.\" Here, \"<Character Name A> and <Character Name B>\" are the conditions for the [Union-Fusion] skill."},{"id":"22-13-4-2","text":"[Union-Fusion] can be activated by revealing 1 of each of the specified character's Battle Cards from your hand, with each Battle Card's power being equal. If such a set of cards can't be revealed, you can't declare activation of [Union-Fusion]."},{"id":"22-13-4-2-1","text":"Some card text reads \"you can choose Battle Cards in one of your areas when choosing cards to use with this card's [Union- Fusion] skill.\" These skills expand the conditions that can be fulfilled when choosing cards for a given keyword skill."},{"id":"22-13-4-3","text":"[Union-Fusion] can only be activated from a player's hand."},{"id":"22-13-4-4","text":"When activating [Union-Fusion], players place one of each of the specified Battle Cards with the same power from their hand in the Drop Area as the skill cost."},{"id":"22-13-4-4-1","text":"Then, if there is a necessary skill cost, determine that cost and then pay it in its entirety."},{"id":"22-13-4-5","text":"To resolve the effects of [Union-Fusion], players play the Battle Card that activated the skill."},{"id":"22-13-4-5-1","text":"If a card that activated [Union-Fusion] fails to enter play, it is placed in its owner's Drop Area."},{"id":"22-13-4-5-1-1","text":"As an exception to the above rule, if a skill states that a card is \"returned to its owner's hand instead of being played,\" cards returned to a player's hand by such a skill are not placed in their owner's Drop Area."},{"id":"22-13-5","text":"[Union-Potara]"},{"id":"22-13-5-1","text":"[Union-Potara] is described as follows: \"[Union-Potara] skill cost : <Character Name A> and <Character Name B>.\" Here, \"<Character Name A> and <Character Name B>\" are the conditions for the [Union-Potara] skill."},{"id":"22-13-5-2","text":"[Union-Potara] can be activated by paying the skill cost and choosing one of each specified character's Battle Card in your Battle Area. If the player can't choose all of the specified Battle Cards, they can't activate [Union-Potara]."},{"id":"22-13-5-2-1","text":"Some card text reads \"you can choose Battle Cards in one of your areas when choosing cards to use with this card's [Union- Potara] skill.\" These skills expand the conditions that can be fulfilled when choosing cards for a given keyword skill."},{"id":"22-13-5-2-1-1","text":"When using such a skill to choose Battle Cards from an expanded range of areas, if the skill resolution would cause the card that activated [Union-Potara] to be played, first move any Battle Cards in that area to the Battle Area, and then resolve the keyword skill normally. Furthermore, any area movement triggers resulting from the chosen Battle Card moving to a different area are not made pending, nor does counter timing occur."},{"id":"22-13-5-3","text":"[Union-Potara] can only be activated from a player's hand."},{"id":"22-13-5-4","text":"To resolve the effects of [Union-Potara], the card that activated the skill is played by placing it on top of the two Battle Cards chosen in 22-13-5-2, which can be in any order."},{"id":"22-13-5-4-1","text":"All continuous effects affecting the power of the played Battle Cards carry over."},{"id":"22-13-5-4-2","text":"If a card that activated [Union-Potara] fails to enter play, it is placed in its owner's Drop Area."},{"id":"22-13-5-4-2-1","text":"As an exception to the above rule, if a skill states that a card is \"returned to its owner's hand instead of being played,\" cards returned to a player's hand by such a skill are not placed in their owner's Drop Area."},{"id":"22-13-6","text":"[Union-Absorb]"},{"id":"22-13-6-1","text":"[Union-Absorb] is described as follows: \"[Union-Absorb] skill cost : effect.\""},{"id":"22-13-6-2","text":"[Union-Absorb] can only be activated from the Battle Area."},{"id":"22-13-6-3","text":"To resolve the effects of [Union-Absorb], one specified Battle Card in the area specified by the effect is played on top of the card that activated the skill."},{"id":"22-13-6-3-1","text":"All continuous effects affecting the position or power of the played cards carry over."},{"id":"22-13-6-3-2","text":"If a Battle Card chosen for a [Union-Absorb] effect fails to enter play, it is placed in its owner's Drop Area."},{"id":"22-13-6-3-2-1","text":"As an exception to the above rule, if a skill states that a card is \"returned to its owner's hand instead of being played,\" cards returned to a player's hand by such a skill are not placed in their owner's Drop Area."}]},
  {"name":"Over Realm","tag":"[Over Realm X]","spellings":["over realm","dark over realm"],"section":"22-15, 22-23","meaning":"With X or more cards in your Drop Area — X or more black cards, for the dark one — send your whole Drop Area to the Warp as the cost and play this card from hand. The two share one activation a turn. A card played with [Over Realm] goes to the Warp at the end of that turn.","manual":[{"id":"22-15-1","text":"This [Activate : Main] keyword skill is related to playing cards."},{"id":"22-15-2","text":"[Over Realm] is described as follows: \"[Over Realm X] skill cost :\" or \"[Over Realm X] skill cost.\""},{"id":"22-15-3","text":"[Over Realm] can be activated if you have X or more cards in your Drop Area. If your Drop Area does not have at least the specified number of cards, [Over Realm] can't be activated."},{"id":"22-15-4","text":"To activate [Over Realm], send all the cards in your Drop Area to your Warp as the skill cost."},{"id":"22-15-5","text":"[Over Realm] can only be activated from a player's hand."},{"id":"22-15-6","text":"To resolve the effects of [Over Realm], play the card that activated the skill. If a card played using [Over Realm] is still in the Battle Area at the end of the turn when it was played, that card is sent to its owner's Warp."},{"id":"22-15-7","text":"[Over Realm] and [Dark Over Realm] can only be activated a combined total of once per turn."},{"id":"22-23-1","text":"This [Activate : Main] keyword skill is related to playing cards."},{"id":"22-23-2","text":"[Dark Over Realm] is described as follows: \"[Dark Over Realm X] skill cost :\" or \"[Dark Over Realm X] skill cost.\""},{"id":"22-23-3","text":"[Dark Over Realm] can be activated if you have X or more black cards in your Drop Area. If your Drop Area does not have at least the specified number of cards, [Dark Over Realm] can't be activated."},{"id":"22-23-4","text":"To activate [Dark Over Realm], send all the cards in your Drop Area to your Warp as the skill cost."},{"id":"22-23-5","text":"[Dark Over Realm] can only be activated from a player's hand."},{"id":"22-23-6","text":"To resolve the effects of [Dark Over Realm], play the card that activated the skill."},{"id":"22-23-7","text":"[Over Realm] and [Dark Over Realm] can only be activated a combined total of once per turn."}]},
  {"name":"Swap","tag":"[Swap X]","spellings":["swap"],"section":"22-22","meaning":"Return this Battle Card to your hand and play a named Battle Card with an energy cost of X from your hand in its place.","manual":[{"id":"22-22-1","text":"This [Activate : Main] keyword skill is related to playing cards."},{"id":"22-22-2","text":"[Swap] is described as follows: \"[Swap X] skill cost : specified Battle Card with an energy cost of X.\""},{"id":"22-22-3","text":"To activate [Swap], reveal up to one specified Battle Card from your hand with an energy cost of X, and then return the Battle Card that activated [Swap] to your hand. If you can't choose the specified Battle Card or return the card that declared the activation of [Swap] to your hand, you can't activate [Swap]."},{"id":"22-22-4","text":"To resolve [Swap], play up to one specified Battle Card revealed from your hand with an energy cost of X as the skill cost."}]},
  {"name":"Arrival","tag":"[Arrival XY]","spellings":["arrival"],"section":"22-29","meaning":"During a battle, when the original colours of the Battle Cards in your Combo Area cover every colour named, pay the cost and play this card from hand.","manual":[{"id":"22-29-1","text":"This [Activate : Battle] keyword skill is related to playing cards."},{"id":"22-29-2","text":"[Arrival] is described as follows: \"[Arrival XY] skill cost :\" or [Arrival XY] skill cost.\""},{"id":"22-29-3","text":"[Arrival] can be activated when the original colors of the Battle Cards in your Combo Area match the colors specified by [Arrival] (X and Y). If the conditions can't be fulfilled or the skill cost can't be paid, [Arrival] can't be activated."},{"id":"22-29-4","text":"[Arrival] can only be activated from a player's hand."},{"id":"22-29-5","text":"To resolve the effects of [Arrival], play the card that activated [Arrival]."},{"id":"22-29-6","text":"Some card text refers to [Arrival] skills. This refers to [Arrival] with any color combination."}]},
  {"name":"Successor","tag":"[Successor]","spellings":["successor"],"section":"22-38","meaning":"Drop any number of mono-green, mono-yellow or Green/Yellow Battle Cards from your Battle Area whose energy costs add up to exactly this card's printed cost, and play it from hand.","manual":[{"id":"22-38-1","text":"This [Activate: Main] keyword skill is related to playing cards."},{"id":"22-38-2","text":"[Successor] is described as follows: \"[Successor] skill cost :\" or \"[Successor] skill cost.\""},{"id":"22-38-3","text":"[Successor] can be activated by choosing any number of mono-green, mono-yellow, and/or Green/Yellow multicolor Battle Cards in your Battle Area whose energy costs add up to the original energy cost of the card with [Successor] and then placing those cards in your Drop Area."},{"id":"22-38-4","text":"[Successor] can only be activated from its owner's hand."},{"id":"22-38-5","text":"To resolve the effects of [Successor], play the Battle Card that activated this skill."}]},
  {"name":"Revive","tag":"[Revive XY]","spellings":["revive"],"section":"22-34","meaning":"When this Battle Card is KO'd, drop cards from hand whose original colours cover both named colours to play it back from your Drop Area. [Revive] is then negated on it for the turn.","manual":[{"id":"22-34-1","text":"This [Auto] keyword skill is related to playing cards."},{"id":"22-34-2","text":"[Revive] is described as follows: \"[Revive XY]\" or \"[Revive XY] skill cost :\""},{"id":"22-34-3","text":"When a Battle Card with [Revive] is KO'd, its owner can activate [Revive] by placing one or more cards whose original colors match both X and Y from their hand into their Drop Area as its skill cost. Then, if there is an additional skill cost, determine that cost and pay it."},{"id":"22-34-4","text":"The effects of [Revive] are resolved as follows: \"The card that activated [Revive] is played from its owner's Drop Area, and [Revive] is negated on that card for the duration of the turn.\""}]},
  {"name":"Offering","tag":"[Offering]","spellings":["offering"],"section":"22-33","meaning":"When this Battle Card is played, your opponent may put one of their life cards in their Drop Area. If they don't, you draw 2 cards.","manual":[{"id":"22-33-1","text":"This [Auto] keyword skill is related to playing cards."},{"id":"22-33-2","text":"When a Battle Card with [Offering] is played, it is made pending."},{"id":"22-33-3","text":"The effects of [Offering] are resolved as follows: \"The opponent of the player who played the card with [Offering] may place a card from their life in their Drop Area. If they don't, the owner of the card with [Offering] draws 2 cards.\""}]},
  {"name":"Heroic","tag":"[Heroic]","spellings":["heroic"],"section":"22-35","meaning":"When you play another Battle Card with [Heroic], or activate a [Heroic] Extra Card skill, draw 1 card, then negate the effects of this skill for the rest of the turn.","manual":[{"id":"22-35-1","text":"This [Auto] keyword skill is related to the player's hand."},{"id":"22-35-2","text":"[Heroic] is made pending when its owner plays another Battle Card with Heroic or activates a Heroic Extra Card's skill."},{"id":"22-35-3","text":"The effects of [Heroic] are resolved as follows: \"Draw 1 card and negate the effects of this skill for the duration of the turn.\""}]},
  {"name":"Villainous","tag":"[Villainous]","spellings":["villainous"],"section":"22-36","meaning":"When you play another Battle Card with [Villainous], or activate a [Villainous] Extra Card skill, your opponent chooses a card in their hand and drops it; the skill is then negated for the rest of the turn.","manual":[{"id":"22-36-1","text":"This [Auto] keyword skill is related to the player's hand."},{"id":"22-36-2","text":"[Villainous] is made pending when its owner plays another Battle Card with Villainous or activates a Villainous Extra Card's skill."},{"id":"22-36-3","text":"The effects of [Villainous] are resolved as follows: \"Make the opponent choose 1 card from their hand and place it in their Drop Area, and negate the effects of this skill for the duration of the turn.\""}]},
  {"name":"Unique","tag":"[Unique]","spellings":["unique"],"section":"22-39","meaning":"While a card with [Unique] is in play you can't play another card with the same name. If two are somehow in play at once, their master keeps one and drops the rest.","manual":[{"id":"22-39-1","text":"This [Permanent] keyword skill is related to playing cards."},{"id":"22-39-2","text":"If a card with [Unique] is in play, no other cards with the same name can be played in its owner's Battle Area. This skill is valid in all areas."},{"id":"22-39-3","text":"If a card with [Unique] is already in play, its owner can't play another card with the same card name as that card."},{"id":"22-39-4","text":"If two or more cards with [Unique] and the same card name are in play in the same Battle Area, their master chooses one of the cards to keep in play, placing any remaining cards with the same card name in their Drop Areas (21-11)."}]},
  {"name":"Overlord","tag":"[Overlord]","spellings":["overlord"],"section":"22-41","meaning":"Put one of your Battle Cards with [Servant] at the bottom of your deck as the cost, and draw 1 card.","manual":[{"id":"22-41-1","text":"This [Activate : Main] keyword skill is related to the player's hand."},{"id":"22-41-2","text":"[Overlord] is activated by placing one of your Battle Cards with [Servant] at the bottom of its owner's deck as the skill cost."},{"id":"22-41-3","text":"To resolve the effects of [Overlord], the player who activated this skill draws 1 card."}]},
  {"name":"Rejuvenate","tag":"[Rejuvenate]","spellings":["rejuvenate"],"section":"22-42","meaning":"A Unison Card with cards beneath it: drop one of them and pay the skill cost, then add the top card of your deck to your life.","manual":[{"id":"22-42-1","text":"This [Activate : Main] keyword skill is related to life."},{"id":"22-42-2","text":"[Rejuvenate] is described as follows: \"[Rejuvenate] skill cost :\" or \"[Rejuvenate] skill cost.\""},{"id":"22-42-3","text":"[Rejuvenate] can be activated by placing a card from beneath the card activating [Rejuvenate] in its owner's Drop Area and paying the skill cost."},{"id":"22-42-4","text":"A player who activates [Rejuvenate] can add the top card of their deck to their life."}]},
  {"name":"Empower","tag":"[Empower Y]","spellings":["empower","empower blue"],"section":"22-45","meaning":"When you play this Unison Card over one whose colour matches, you may move up to Y markers from the Unison being replaced onto this one. An [Empower] naming no colour takes them from a Unison of any colour.","manual":[{"id":"22-45-1","text":"This [Permanent] keyword skill is related to markers."},{"id":"22-45-2","text":"[Empower] is described as follows: \"[Empower XY].\" X specifies a color, and Y specifies a number."},{"id":"22-45-3","text":"[Empower] can be activated from all areas. If you have one or more Unison Cards with a color matching X in play in your Unison Area, if those Unison Cards are placed in your Drop Area when you play a Unison Card with [Empower], you may add up to Y markers from 1 of the Unison Cards whose colors match X to the Unison Card with this skill as you play it."},{"id":"22-45-3-1","text":"If there are multiple colors specified by [Empower] (for example, [Empower XY/ZY]), you choose one of the colors, and then add up to Y markers from Unison Cards whose colors match the color you chose and are placed in your Drop Area to the Unison Card with this skill as you play it (13-2-1-3-1) (13-2-2-5-1)."},{"id":"22-45-3-2","text":"Some [Empower] skills don't specify a color. In these cases, Unison Cards of any color can be placed in your Drop Area."}]},
  {"name":"Blocker","tag":"[Blocker]","spellings":["blocker"],"section":"22-4","meaning":"When one of your other cards is attacked, switch this card to Rest Mode to become the guard card instead.","manual":[{"id":"22-4-1","text":"This [Auto] keyword skill is related to battle."},{"id":"22-4-2","text":"[Blocker] can be activated by switching the card with this skill to Rest Mode as the skill cost when one of your cards other than the one with this skill is attacked and made pending (8-1-3)."},{"id":"22-4-3","text":"The effects of [Blocker] are resolved as follows: \"Switch the guard card of the attack to the card that activated [Blocker].\""},{"id":"22-4-3-1","text":"When [Blocker] is used to switch a guard card to the card that activated [Blocker], any [Auto] skills on that card that trigger \"when this card is attacked\" enter pending (1-5-6-4)."},{"id":"22-4-4","text":"\"Negate [Blocker]\" is a special procedure in which the target of the attack (the guard card) is switched back to the original target."}]},
  {"name":"Critical","tag":"[Critical]","spellings":["critical"],"section":"22-6","meaning":"Life damage this card deals by attacking goes to the opponent's Drop Area instead of their hand.","manual":[{"id":"22-6-1","text":"This [Permanent] keyword skill is related to damage."},{"id":"22-6-2","text":"[Critical] is described as follows: \"When this card inflicts damage to your opponent's life by attacking, they place that many Life Area cards in their Drop Area instead of their hand during the damage processing (21-3).\""}]},
  {"name":"Strike","tag":"[Double Strike]","spellings":["double strike","triple strike","quadruple strike"],"section":"22-7","meaning":"When this card would deal less than X life damage by attacking, it deals X instead — 2, 3 or 4.","manual":[{"id":"22-7-1","text":"This [Permanent] keyword skill is related to damage."},{"id":"22-7-2","text":"[Strike] is described as follows: \"When this card inflicts damage to your opponent's life by attacking, if it deals X-1 damage or less, this card inflicts X damage instead.\""},{"id":"22-7-2-1","text":"The X of [Double Strike] is 2."},{"id":"22-7-2-2","text":"The X of [Triple Strike] is 3."},{"id":"22-7-2-3","text":"The X of [Quadruple Strike] is 4."},{"id":"22-7-3","text":"Some card text refers to [Strike] skills. This refers to [Double Strike], [Triple Strike], and [Quadruple Strike] skills."}]},
  {"name":"Attack","tag":"[Dual Attack]","spellings":["dual attack","triple attack"],"section":"22-8","meaning":"When this card attacks, it switches back to Active Mode at the end of the battle — X−1 times a turn.","manual":[{"id":"22-8-1","text":"This [Auto] keyword skill is related to battle."},{"id":"22-8-2","text":"When a card with [X Attack] attacks, this card is made pending."},{"id":"22-8-3","text":"The effects of [X Attack] are resolved as follows: \"When this card attacks, switch this card to Active Mode at the end of battle.\" The skill activates X-1 times per turn."},{"id":"22-8-3-1","text":"The X of [Dual Attack] is 2."},{"id":"22-8-3-2","text":"The X of [Triple Attack] is 3."}]},
  {"name":"Revenge","tag":"[Revenge]","spellings":["revenge"],"section":"22-9","meaning":"When this card becomes the guard card, KO the attacking card at the end of the battle.","manual":[{"id":"22-9-1","text":"This [Auto] keyword skill is related to battle."},{"id":"22-9-2","text":"[Revenge] can only be activated by Battle Cards and Unison Cards with the skill."},{"id":"22-9-3","text":"[Revenge] is described as follows: when this card becomes a guard card, it is made pending."},{"id":"22-9-4","text":"The effects of [Revenge] are resolved as follows: \"KO the attack card at the end of the battle.\""}]},
  {"name":"Alliance","tag":"[Alliance XY]","spellings":["alliance"],"section":"22-32","meaning":"When this card attacks, you may switch one or more of your other Battle Cards of the named colours to Rest Mode as the cost of the printed effect.","manual":[{"id":"22-32-1","text":"This [Auto] keyword skill is related to attacking."},{"id":"22-32-2","text":"[Alliance] is described as follows: \"[Alliance XY] (effect)\" or \"[Alliance XY] skill cost : effect.\""},{"id":"22-32-3","text":"When a card with [Alliance] attacks, that card is made pending, and its owner may activate [Alliance] by choosing one or more Battle Cards in their Battle Area with colors that match the colors specified by [Alliance] (X and Y) and switching them from Active Mode to Rest Mode as part of its skill cost."},{"id":"22-32-4","text":"To resolve the effects of [Alliance], execute the specified effects."}]},
  {"name":"Aegis","tag":"[Aegis XY]","spellings":["aegis"],"section":"22-30","meaning":"In the Defense Step of your opponent's turn, drop cards from your hand covering the named colours to switch up to two of your energy from Rest to Active Mode.","manual":[{"id":"22-30-1","text":"This [Activate : Battle] keyword skill is related to energy."},{"id":"22-30-2","text":"[Aegis] is described as follows: \"[Aegis XY]\" or \"[Aegis XY] skill cost.\""},{"id":"22-30-3","text":"[Aegis] can be activated when you place one each of the cards whose original colors match those specified by [Aegis] (X and Y) from your hand into your Drop Area as part of the skill cost. This includes placing cards such as 1 blue single-color card and 1 yellow single-color card, or 1 Blue/Yellow multicolor card. Then, if there is an additional skill cost, determine that cost and pay it."},{"id":"22-30-4","text":"[Aegis] can only be activated during the Defense Step of your opponent's turn."},{"id":"22-30-5","text":"To resolve the effects of [Aegis], a player who activates [Aegis] chooses up to two of their energy and switches them from Rest Mode to Active Mode."}]},
  {"name":"Victory Strike","tag":"[Victory Strike]","spellings":["victory strike"],"section":"22-18","meaning":"Deal life damage by attacking with this card and you win the game.","manual":[{"id":"22-18-1","text":"This [Permanent] keyword skill is related to damage and victory conditions."},{"id":"22-18-2","text":"[Victory Strike] is described as follows: \"When you deal life damage by attacking with this card, you win the game.\""}]},
  {"name":"Servant","tag":"[Servant]","spellings":["servant"],"section":"22-40","meaning":"+10000 power, and the card does not switch to Active Mode during its master's Charge Phase.","manual":[{"id":"22-40-1","text":"This [Permanent] keyword skill is related to power and position."},{"id":"22-40-2","text":"Cards with [Servant] get +10000 power but can't be switched to Active Mode during their masters' Charge Phases."}]},
  {"name":"Barrier","tag":"[Barrier]","spellings":["barrier"],"section":"22-16","meaning":"This card can't be chosen by the skills of cards your opponent masters.","manual":[{"id":"22-16-1","text":"This [Permanent] keyword skill is related to skill targets."},{"id":"22-16-2","text":"[Barrier] is described as follows: \"This card can't be chosen by the skills of cards mastered by your opponent.\""}]},
  {"name":"Deflect","tag":"[Deflect]","spellings":["deflect"],"section":"22-20","meaning":"This card isn't affected by your opponent's [Counter: Play] skills. Valid in every area.","manual":[{"id":"22-20-1","text":"This [Permanent] keyword skill is related to playing cards."},{"id":"22-20-2","text":"[Deflect] is described as follows and is valid in all areas: \"This card isn't affected by your opponent's [Counter : Play] skills.\""}]},
  {"name":"Indestructible","tag":"[Indestructible]","spellings":["indestructible"],"section":"22-12","meaning":"This card can't be KO'd or moved out of your Battle Area by the opponent's skills or as a result of battle.","manual":[{"id":"22-12-1","text":"This [Permanent] keyword skill is related to movement between areas."},{"id":"22-12-2","text":"[Indestructible] is described as follows: \"This card can't be KO'd or removed from your Battle Area by the opponent's card skills or as a result of battle.\""}]},
  {"name":"Energy-Exhaust","tag":"[Energy-Exhaust]","spellings":["energy-exhaust"],"section":"22-31","meaning":"When this card is placed in an Energy Area, it arrives in Rest Mode. Valid in every area.","manual":[{"id":"22-31-1","text":"This [Permanent] keyword skill is related to energy."},{"id":"22-31-2","text":"If a card with [Energy-Exhaust], which is valid in all areas, is placed in an Energy Area as energy, it must be placed there in Rest Mode."}]},
  {"name":"Warrior of Universe 7","tag":"[Warrior of Universe 7]","spellings":["warrior of universe"],"section":"22-19","meaning":"Treat your ≪Universe 7≫ cards in every area as having no specified cost — the coloured part of a play's price.","manual":[{"id":"22-19-1","text":"This [Permanent] keyword skill is related to energy costs."},{"id":"22-19-2","text":"[Warrior of Universe 7] is described as follows: \"Treat your Universe 7 cards in all areas as if they had no specified cost (1-2-3-2-2).\""}]},
  {"name":"Invoker","tag":"[Invoker]","spellings":["invoker"],"section":"22-37","meaning":"A Red/Blue multicolour Extra Card in your hand may be activated by switching one active Red/Blue multicolour energy to Rest Mode instead of paying its energy cost.","manual":[{"id":"22-37-1","text":"This [Permanent] keyword skill is related to energy costs."},{"id":"22-37-2","text":"[Invoker] allows its owner to activate a Red/Blue multicolor Extra Card in their hand without paying its energy cost by switching an Active Mode Red/Blue multicolor card in their Energy Area to Rest Mode."}]},
  {"name":"Wormhole","tag":"[Wormhole]","spellings":["wormhole"],"section":"22-24","meaning":"[Over Realm] and [Dark Over Realm] may be activated twice a turn between them instead of once.","manual":[{"id":"22-24-1","text":"This [Permanent] keyword skill is related to skill activation."},{"id":"22-24-2","text":"Normally, \"[Over Realm] and [Dark Over Realm] can only be activated a combined total of once per turn (22-15-7) (22-23-7),\" but [Wormhole] has the following effect: \"You can activate [Over Realm] and [Dark Over Realm] up to a total of 2 times a turn.\""}]},
  {"name":"Spirit Boost","tag":"[Spirit Boost X]","spellings":["spirit boost"],"section":"22-43","meaning":"Part of a skill's cost: remove X markers from your Unison Card. A skill whose [Spirit Boost] can't be paid can't be activated.","manual":[{"id":"22-43-1","text":"This keyword is related to skill activation."},{"id":"22-43-2","text":"[Spirit Boost] is described as follows: \"[Spirit Boost X]\" or \"[Spirit Boost X] specified Unison Card.\""},{"id":"22-43-3","text":"A skill with [Spirit Boost X] can be activated by removing X markers from your Unison Card as the skill cost."},{"id":"22-43-3-1","text":"If the card text indicates a specified Unison Card, markers must be removed from the specified Unison Card."}]},
  {"name":"Ultimate","tag":"[Ultimate]","spellings":["ultimate"],"section":"22-14","meaning":"A deck may hold at most one card with [Ultimate], and a card with it that leaves play is removed from the game rather than going anywhere else.","manual":[{"id":"22-14-1","text":"This [Permanent] keyword skill is related to deck construction conditions (6-1-5-2)."},{"id":"22-14-2","text":"[Ultimate] is described as follows: \"A player may only have up to one card with [Ultimate] in their deck.\""},{"id":"22-14-3","text":"If a player's card with [Ultimate] in a Battle Area or Unison Area is moved out of that player's Battle Area or Unison Area--in addition to cases where the card is \"removed from the game\"--the card is removed from the game instead (21-12)."},{"id":"22-14-3-1","text":"If a card with [Ultimate] is moved out of an area due to an effect, and then that card is removed from the game, that card is considered to have been removed from the game by that effect (23-3-2-5)."},{"id":"22-14-3-1-1","text":"22-14-3-1 also applies when a card is in Hidden Mode. (23-5-2-5)"},{"id":"22-14-4","text":"If a card with [Ultimate] fails to enter play, that card is removed from the game instead of being placed in the Drop Area (5-5-4) (21-12)."},{"id":"22-14-5","text":"If the activation of an Extra Card with [Ultimate] is declared and the card is placed in the Drop Area, after the skill is resolved, the card is removed from the game. In addition, even if the skill can't be resolved due to an effect, the card is removed from the game anyway. (21-12)"}]},
  {"name":"Super Combo","tag":"[Super Combo]","spellings":["super combo"],"section":"22-17","meaning":"A deck may hold at most four cards with [Super Combo], counted across all of them.","manual":[{"id":"22-17-1","text":"This [Permanent] keyword skill is related to deck construction conditions (6-1-5-2)."},{"id":"22-17-2","text":"[Super Combo] is described as follows: \"You can only include up to four cards with [Super Combo] in a deck.\""}]},
  {"name":"Dragon Ball","tag":"[Dragon Ball]","spellings":["dragon ball"],"section":"22-28","meaning":"As many copies of a [Dragon Ball] card as you like, as long as no more than seven [Dragon Ball] cards are in the deck all told.","manual":[{"id":"22-28-1","text":"This [Permanent] keyword skill is related to deck construction conditions (6-1-5-2)."},{"id":"22-28-2","text":"[Dragon Ball] is described as follows: \"You can include as many copies of cards with [Dragon Ball] with the same card number in your deck as you like, as long as the total number doesn't exceed 7.\""}]},
];
